toolScript:
const synth = window.speechSynthesis;
        const textInput = document.getElementById('tts-input');
        const voiceSelect = document.getElementById('voice-select');
        const pitch = document.getElementById('pitch');
        const rate = document.getElementById('rate');
        const playBtn = document.getElementById('play-btn');
        const playIcon = document.getElementById('play-icon');
        const playText = document.getElementById('play-text');
        const wordDisplay = document.getElementById('word-display');
        const visualizer = document.getElementById('visualizer');
        const sideWordCount = document.getElementById('side-word-count');
        let voices = [];
        let utterance = null;
        let isPaused = false;
        function populateVoices() {
            voices = synth.getVoices().sort((a, b) => {
                const aname = a.name.toUpperCase();
                const bname = b.name.toUpperCase();
                if (aname < bname) return -1;
                else if (aname == bname) return 0;
                return +1;
            });
            const selectedIndex = voiceSelect.selectedIndex < 0 ? 0 : voiceSelect.selectedIndex;
            voiceSelect.innerHTML = '';
            if (voices.length === 0) {
                const option = document.createElement('option');
                option.textContent = 'No voices found on this system.';
                voiceSelect.appendChild(option);
                return;
            }
            for (let i = 0; i < voices.length; i++) {
                const option = document.createElement('option');
                option.textContent = `${voices[i].name} (${voices[i].lang})`;
                if (voices[i].default) option.textContent += ' -- DEFAULT';
                option.setAttribute('data-lang', voices[i].lang);
                option.setAttribute('data-name', voices[i].name);
                voiceSelect.appendChild(option);
            }
            voiceSelect.selectedIndex = selectedIndex;
        }
        populateVoices();
        if (speechSynthesis.onvoiceschanged !== undefined) {
            speechSynthesis.onvoiceschanged = populateVoices;
        }
        function toggleSpeech() {
            if (synth.speaking && !isPaused) {
                synth.pause();
                isPaused = true;
                setPlayState(false, true);
            } else if (isPaused) {
                synth.resume();
                isPaused = false;
                setPlayState(true);
            } else {
                speak();
            }
        }
        function stopSpeech() {
            synth.cancel();
            isPaused = false;
            setPlayState(false);
            wordDisplay.innerHTML = '<span class="opacity-40 text-[10px] font-black uppercase tracking-[0.3em]">Signal Buffer Idle</span>';
        }
        function speak() {
            if (synth.speaking) {
                synth.cancel();
            }
            if (textInput.value !== '') {
                utterance = new SpeechSynthesisUtterance(textInput.value);
                const selectedOption = voiceSelect.selectedOptions[0].getAttribute('data-name');
                for (let i = 0; i < voices.length; i++) {
                    if (voices[i].name === selectedOption) {
                        utterance.voice = voices[i];
                        break;
                    }
                }
                utterance.pitch = pitch.value;
                utterance.rate = rate.value;
                utterance.volume = document.getElementById('volume').value;
                utterance.onend = function (event) {
                    setPlayState(false);
                    wordDisplay.innerHTML = '<span class="opacity-40 text-[10px] font-black uppercase tracking-[0.3em]">Transmission Complete</span>';
                };
                utterance.onboundary = function (event) {
                    const text = textInput.value;
                    const wordStart = event.charIndex;
                    let wordEnd = text.indexOf(' ', wordStart);
                    if (wordEnd === -1) wordEnd = text.length;
                    const word = text.substring(wordStart, wordEnd).replace(/[.,\/#!$%\^&\*;:{}=\-_`~()]/g, "");
                    if (word.trim().length > 0) {
                        wordDisplay.innerText = word;
                    }
                };
                synth.speak(utterance);
                setPlayState(true);
            }
        }
        function setPlayState(isPlaying, isPausedState = false) {
            if (isPlaying) {
                playText.innerText = "SUSPEND";
                playIcon.innerHTML = '<path fill-rule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zM7 8a1 1 0 012 0v4a1 1 0 11-2 0V8zm5-1a1 1 0 00-1 1v4a1 1 0 102 0V8a1 1 0 00-1-1z" clip-rule="evenodd"></path>';
                visualizer.classList.add('playing');
                visualizer.style.opacity = '1';
            } else {
                if (isPausedState) {
                    playText.innerText = "RESUME";
                    playIcon.innerHTML = '<path fill-rule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM9.555 7.168A1 1 0 008 8v4a1 1 0 001.555.832l3-2a1 1 0 000-1.664l-3-2z" clip-rule="evenodd"></path>';
                    visualizer.classList.remove('playing');
                    visualizer.style.opacity = '0.5';
                } else {
                    playText.innerText = "READ ALOUD";
                    playIcon.innerHTML = '<path fill-rule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM9.555 7.168A1 1 0 008 8v4a1 1 0 001.555.832l3-2a1 1 0 000-1.664l-3-2z" clip-rule="evenodd"></path>';
                    visualizer.classList.remove('playing');
                    visualizer.style.opacity = '0.3';
                }
            }
        }
        function updateLabel(id, value) {
            document.getElementById(id + '-val').innerText = value;
        }
        function updateStats() {
            const words = textInput.value.trim().split(/\s+/).length;
            sideWordCount.innerText = textInput.value.trim() === "" ? "0 Words" : `${words} Words`;
        }
        function clearText() {
            if (!confirm("Purge current text buffer?")) return;
            textInput.value = '';
            stopSpeech();
            updateStats();
        }
        function loadSample() {
            textInput.value = "Welcome to the TTS Simulator. This tool is designed to catch the errors your eyes miss. Listen to the flow of your writing. Notice how commas create pauses, and how short sentences create punch. Try changing the speed to 1.5x to check for logical momentum. Accuracy is built in the auditory channel.";
            updateStats();
        }
        // Event Listeners
        textInput.addEventListener('input', updateStats);
        document.getElementById('rate').addEventListener('input', e => updateLabel('rate', e.target.value + 'x'));
        document.getElementById('pitch').addEventListener('input', e => updateLabel('pitch', e.target.value));
        document.getElementById('volume').addEventListener('input', e => updateLabel('vol', Math.round(e.target.value * 100) + '%'));
        document.addEventListener('DOMContentLoaded', () => {
            updateStats();
        });
        window.addEventListener('beforeunload', () => synth.cancel());
